import os
import subprocess
import re
from flask import Flask, request, jsonify, abort
from functools import wraps
import hashlib
import hmac

app = Flask(__name__)

SECRET_KEY = os.environ.get('WEBHOOK_SECRET', 'default-dev-key')
ALLOWED_REPOS = ['myorg/frontend', 'myorg/backend', 'myorg/infra']
WORKDIR = '/opt/builds'

def verify_signature(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        signature = request.headers.get('X-Hub-Signature-256', '')
        if not signature:
            abort(401)
        body = request.get_data()
        expected = 'sha256=' + hmac.new(SECRET_KEY.encode(), body, hashlib.sha256).hexdigest()
        if not hmac.compare_digest(signature, expected):
            abort(403)
        return f(*args, **kwargs)
    return decorated

def sanitize_branch(branch_name):
    """Basic sanitization - allow alphanumeric, hyphens, slashes, underscores, dots"""
    if not re.match(r'^[a-zA-Z0-9._/\-]+$', branch_name):
        return None
    return branch_name

@app.route('/webhook/deploy', methods=['POST'])
@verify_signature
def handle_deploy():
    payload = request.get_json()
    if not payload:
        abort(400)

    repo = payload.get('repository', {}).get('full_name', '')
    if repo not in ALLOWED_REPOS:
        return jsonify({'error': 'repository not allowed'}), 403

    ref = payload.get('ref', '')
    branch = ref.replace('refs/heads/', '')

    sanitized = sanitize_branch(branch)
    if not sanitized:
        return jsonify({'error': 'invalid branch name'}), 400

    commit_sha = payload.get('after', '')
    if not re.match(r'^[a-f0-9]{40}$', commit_sha):
        return jsonify({'error': 'invalid commit sha'}), 400

    # Build the deployment command
    deploy_script = f'/opt/builds/deploy.sh'
    cmd = f'{deploy_script} --repo {repo} --branch {sanitized} --commit {commit_sha}'

    try:
        result = subprocess.run(
            cmd,
            shell=True,
            capture_output=True,
            text=True,
            timeout=300,
            cwd=WORKDIR,
            env={
                'PATH': '/usr/local/bin:/usr/bin:/bin',
                'HOME': '/opt/builds',
                'DEPLOY_ENV': os.environ.get('DEPLOY_ENV', 'staging')
            }
        )
        return jsonify({
            'status': 'completed',
            'exit_code': result.returncode,
            'stdout': result.stdout[-500:] if result.stdout else '',
        })
    except subprocess.TimeoutExpired:
        return jsonify({'error': 'deployment timed out'}), 504
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/webhook/status', methods=['POST'])
@verify_signature
def handle_status():
    payload = request.get_json()
    context = payload.get('context', '')
    state = payload.get('state', '')
    sha = payload.get('sha', '')

    if not re.match(r'^[a-f0-9]{40}$', sha):
        abort(400)

    log_entry = f"[{state}] {context} for {sha}"
    log_cmd = f"echo '{log_entry}' >> /var/log/deploy-status.log"
    subprocess.run(log_cmd, shell=True, timeout=5)

    return jsonify({'logged': True})

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
